class Solution1 {
public:
    void nextPermutation(vector<int>& nums) {
        int n = nums.size();
        int i = n - 2;
        // Step 1: Find first decreasing element from right
        while (i >= 0 && nums[i] >= nums[i + 1]) {
            i--;
        }
        // now i is the index of the first element that is smaller than its next element from the right
        // Step 2: Swap with the smallest element in suffix larger than nums[i]
        if (i >= 0) {
            int j = n - 1;
            while (nums[j] <= nums[i]) { // find the first element from the right that is greater than nums[i]
                j--;
            }
            swap(nums[i], nums[j]); // swap the found elements to get the next permutation
        }
        // Step 3: Reverse suffix to get lexicographically smallest order
        reverse(nums.begin() + i + 1, nums.end()); // reveser subarray [i+1, n-1] to get the next permutation
    }
};

class Solution2 {
public:
    int jump(vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 0;
        int jumps = 0;
        int currEnd = 0;
        int farthest = 0;
        // Greedy: Extend max reach within current window
        for (int i = 0; i < n - 1; ++i) {
            farthest = max(farthest, i + nums[i]);
            // Jump to next window when reaching end of current reach
            if (i == currEnd) {
                jumps++;
                currEnd = farthest;
                if (currEnd >= n - 1) break; // Early exit if we can reach or exceed the last index
            }
        }
        return jumps;
    }
};

class Solution3 {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        if (intervals.empty()) return {};
        // Sort intervals by start time
        sort(intervals.begin(), intervals.end());
        vector<vector<int>> merged;
        for (const auto& interval : intervals) {
            // Append if no overlap; otherwise extend the current interval's end
            if (merged.empty() || merged.back()[1] < interval[0]) {
                merged.push_back(interval);
            } else {
                merged.back()[1] = max(merged.back()[1], interval[1]);
            }
        }
        return merged;
    }
};

class Solution4 {
public:
    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
        int totalTank = 0;
        int currTank = 0;
        int start = 0;
        for (int i = 0; i < (int)gas.size(); ++i) {
            int diff = gas[i] - cost[i];
            totalTank += diff;
            currTank += diff;
            // If tank drops below zero, reset start to next station
            if (currTank < 0) {
                start = i + 1;
                currTank = 0;
            }
        }
        // If overall gas >= cost, the circuit can be completed
        return (totalTank >= 0) ? start : -1;
    }
};

class Solution5 {
public:
    int findRadius(vector<int>& houses, vector<int>& heaters) {
        sort(heaters.begin(), heaters.end());
        int maxRadius = 0;
        for (int house : houses) {
            // Binary search nearest heaters to the right and left
            auto it = lower_bound(heaters.begin(), heaters.end(), house);
            int dist = INT_MAX;
            if (it != heaters.end()) {
                dist = min(dist, *it - house);
            }
            if (it != heaters.begin()) {
                dist = min(dist, house - *prev(it));
            }
            // Max radius needed across all houses
            maxRadius = max(maxRadius, dist);
        }
        return maxRadius;
    }
};

class Solution6 {
public:
    int leastInterval(vector<char>& tasks, int n) {
        vector<int> freq(26, 0);
        int maxFreq = 0;
        // Count frequencies of tasks
        for (char c : tasks) {
            freq[c - 'A']++;
            maxFreq = max(maxFreq, freq[c - 'A']);
        }
        // Count how many tasks share the maximum frequency
        int maxCount = 0;
        for (int f : freq) {
            if (f == maxFreq) maxCount++;
        }
        // Frame formula: maxFreq blocks with n idle slots each
        int emptySlots = (maxFreq - 1) * (n + 1) + maxCount;
        return max((int)tasks.size(), emptySlots);
    }
};

class Solution7 {
public:
    vector<int> partitionLabels(string s) {
        vector<int> lastIndex(26, 0);
        // Record last occurrence index of each character
        for (int i = 0; i < (int)s.size(); ++i) {
            lastIndex[s[i] - 'a'] = i;
        }
        vector<int> result;
        int start = 0;
        int currEnd = 0;
        // Greedily expand current partition boundary
        for (int i = 0; i < (int)s.size(); ++i) {
            currEnd = max(currEnd, lastIndex[s[i] - 'a']);
            if (i == currEnd) {
                result.push_back(currEnd - start + 1);
                start = i + 1;
            }
        }
        return result;
    }
};

class Solution8 {
public:
    // Sort start ascending; break ties with end descending
    static bool cmp(const vector<int>& a, const vector<int>& b) {
        return a[0] != b[0] ? a[0] < b[0] : a[1] > b[1];
    }
    int removeCoveredIntervals(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end(), cmp);
        int count = 0, maxEnd = 0;
        // Retain intervals that extend past the maximum seen end point
        for (const auto& interval : intervals) {
            if (interval[1] > maxEnd) {
                count++;
                maxEnd = interval[1];
            }
        }
        return count;
    }
};

class Solution9 {
public:
    int maxEvents(vector<vector<int>>& events) {
        sort(events.begin(), events.end());
        priority_queue<int, vector<int>, greater<int>> minHeap;
        int day = 1;
        int i = 0;
        int n = events.size();
        int attended = 0;
        while (i < n || !minHeap.empty()) {
            // Advance day if no active events in queue
            if (minHeap.empty()) {
                day = events[i][0];
            }
            // Add all events that start by today
            while (i < n && events[i][0] <= day) {
                minHeap.push(events[i][1]);
                i++;
            }
            // Discard expired events
            while (!minHeap.empty() && minHeap.top() < day) {
                minHeap.pop();
            }
            // Greedily attend the event ending earliest
            if (!minHeap.empty()) {
                minHeap.pop();
                attended++;
                day++;
            }
        }
        return attended;
    }
};

class Solution10 {
public:
    int maxItemsFromSale(vector<int>& basePrices, vector<int>& discounts, int budget) {
        int n = basePrices.size();
        vector<int> effectiveCosts(n);
        // Calculate discounted prices
        for (int i = 0; i < n; ++i) {
            effectiveCosts[i] = max(0, basePrices[i] - discounts[i]);
        }
        // Greedily purchase cheapest items first
        sort(effectiveCosts.begin(), effectiveCosts.end());
        int count = 0;
        for (int cost : effectiveCosts) {
            if (budget >= cost) {
                budget -= cost;
                count++;
            } else {
                break;
            }
        }
        return count;
    }
};

class Solution11 {
public:
    int lengthOfLongestSubstring(string s) {
        vector<int> lastIndex(256, -1);
        int left = 0;
        int maxLen = 0;
        // Sliding window: move left pointer past previous occurrence of s[right]
        for (int right = 0; right < (int)s.size(); ++right) {
            unsigned char c = s[right];
            if (lastIndex[c] >= left) {
                left = lastIndex[c] + 1;
            }
            lastIndex[c] = right;
            maxLen = max(maxLen, right - left + 1);
        }
        return maxLen;
    }
};

class Solution12 {
public:
    int maxArea(vector<int>& height) {
        int left = 0;
        int right = (int)height.size() - 1;
        int maxWater = 0;
        // Two pointers: move inward from the shorter wall
        while (left < right) {
            int h = min(height[left], height[right]);
            int w = right - left;
            maxWater = max(maxWater, h * w);
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }
        return maxWater;
    }
};

class Solution13 {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        vector<vector<int>> result;
        int n = nums.size();
        for (int i = 0; i < n - 2; ++i) {
            // Skip duplicates for the first element
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            if (nums[i] > 0) break; // Cannot sum to 0 if smallest is positive
            int left = i + 1;
            int right = n - 1;
            // Two pointers for two-sum target = -nums[i]
            while (left < right) {
                int sum = nums[i] + nums[left] + nums[right];
                if (sum == 0) {
                    result.push_back({nums[i], nums[left], nums[right]});
                    while (left < right && nums[left] == nums[left + 1]) left++;
                    while (left < right && nums[right] == nums[right - 1]) right--;
                    left++;
                    right--;
                } else if (sum < 0) {
                    left++;
                } else {
                    right--;
                }
            }
        }
        return result;
    }
};

class Solution14 {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        vector<vector<int>> result;
        int n = nums.size();
        for (int i = 0; i < n - 3; ++i) {
            if (i > 0 && nums[i] == nums[i - 1]) continue; // Skip duplicates for 1st num
            for (int j = i + 1; j < n - 2; ++j) {
                if (j > i + 1 && nums[j] == nums[j - 1]) continue; // Skip duplicates for 2nd num
                int left = j + 1;
                int right = n - 1;
                // Two pointers for remaining two numbers
                while (left < right) {
                    long long sum = (long long)nums[i] + nums[j] + nums[left] + nums[right];
                    if (sum == target) {
                        result.push_back({nums[i], nums[j], nums[left], nums[right]});
                        while (left < right && nums[left] == nums[left + 1]) left++;
                        while (left < right && nums[right] == nums[right - 1]) right--;
                        left++;
                        right--;
                    } else if (sum < target) {
                        left++;
                    } else {
                        right--;
                    }
                }
            }
        }
        return result;
    }
};

class Solution15 {
public:
    int trap(vector<int>& h) {
        stack<int> st;
        int water = 0;

        for (int i = 0; i < h.size(); i++) {
            while (!st.empty() && h[i] > h[st.top()]) {
                int mid = st.top();
                st.pop();

                if (st.empty()) break;

                int left = st.top();
                int width = i - left - 1;
                int boundedHeight = min(h[left], h[i]) - h[mid];

                water += width * boundedHeight;
            }
            st.push(i);
        }

        return water;
    }
};

class Solution16 {
public:
    void sortColors(vector<int>& nums) {
        int low = 0;
        int mid = 0;
        int high = (int)nums.size() - 1;
        // Dutch National Flag: 3-way partition (0s at low, 2s at high)
        while (mid <= high) {
            if (nums[mid] == 0) {
                swap(nums[low], nums[mid]);
                low++;
                mid++;
            } else if (nums[mid] == 1) {
                mid++;
            } else {
                swap(nums[mid], nums[high]);
                high--;
            }
        }
    }
};

class Solution17 {
public:
    string minWindow(string s, string t) {
        vector<int> need(128, 0);
        int required = 0;
        // Count frequency of required characters
        for (char c : t) {
            if (need[(unsigned char)c] == 0) required++;
            need[(unsigned char)c]++;
        }
        vector<int> window(128, 0);
        int have = 0;
        int bestLen = INT_MAX;
        int bestStart = 0;
        int left = 0;
        // Expand window to the right
        for (int right = 0; right < (int)s.size(); ++right) {
            unsigned char c = s[right];
            window[c]++;
            if (need[c] > 0 && window[c] == need[c]) {
                have++;
            }
            // Contract window from left while condition is satisfied
            while (have == required) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                }
                unsigned char leftChar = s[left];
                window[leftChar]--;
                if (need[leftChar] > 0 && window[leftChar] < need[leftChar]) {
                    have--;
                }
                left++;
            }
        }
        return (bestLen == INT_MAX) ? "" : s.substr(bestStart, bestLen);
    }
};

class Solution19 {
public:
    vector<int> findAnagrams(string s, string p) {
        int ns = s.size(), np = p.size();
        if (ns < np) return {};
        vector<int> pCount(26, 0), sCount(26, 0);
        for (char c : p) pCount[c - 'a']++;
        vector<int> result;
        // Fixed-size sliding window of length |p|
        for (int i = 0; i < ns; ++i) {
            sCount[s[i] - 'a']++;
            if (i >= np) {
                sCount[s[i - np] - 'a']--;
            }
            if (sCount == pCount) {
                result.push_back(i - np + 1);
            }
        }
        return result;
    }
};

class Solution20 {
public:
    bool checkInclusion(string s1, string s2) {
        int n1 = s1.size(), n2 = s2.size();
        if (n1 > n2) return false;
        vector<int> c1(26, 0), c2(26, 0);
        for (char c : s1) c1[c - 'a']++;
        // Sliding window of length |s1| over s2
        for (int i = 0; i < n2; ++i) {
            c2[s2[i] - 'a']++;
            if (i >= n1) {
                c2[s2[i - n1] - 'a']--;
            }
            if (c1 == c2) return true;
        }
        return false;
    }
};

class Solution21 {
    // Helper: count subarrays with at most k distinct elements
    int atMost(vector<int>& nums, int k) {
        unordered_map<int, int> freq;
        int left = 0, ans = 0;
        for (int right = 0; right < nums.size(); right++) {
            freq[nums[right]]++;
            while (freq.size() > k) {
                if (--freq[nums[left]] == 0)
                    freq.erase(nums[left]);
                left++;
            }
            ans += right - left + 1;
        }
        return ans;
    }
public:
    // Exactly(k) = atMost(k) - atMost(k - 1)
    int subarraysWithKDistinct(vector<int>& nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }
};

class Solution22 {
public:
    int maxFrequency(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        long long sum = 0;
        int left = 0, ans = 0;
        // Sliding window: operations needed to make [left..right] equal to nums[right]
        for (int right = 0; right < nums.size(); right++) {
            sum += nums[right];
            while (1LL * nums[right] * (right - left + 1) - sum > k)
                sum -= nums[left++];
            ans = max(ans, right - left + 1);
        }
        return ans;
    }
};

class Solution24 {
public:
    int longestConsecutive(vector<int>& nums) {
        unordered_set<int> st(nums.begin(), nums.end());
        int ans = 0;
        for (int x : st) {
            // Only start count from the beginning of a sequence
            if (st.count(x - 1)) continue;
            int len = 1;
            while (st.count(x + len))
                len++;
            ans = max(ans, len);
        }
        return ans;
    }
};

class Solution25 {
public:
    int majorityElement(vector<int>& nums) {
        int ans = 0, count = 0;
        // Boyer-Moore Voting: find candidate element appearing > n/2 times
        for (int x : nums) {
            if (count == 0) ans = x;
            count += (x == ans) ? 1 : -1;
        }
        return ans;
    }
};

class Solution26 {
public:
    vector<int> majorityElementII(vector<int>& nums) {
        int a = 0, b = 1, ca = 0, cb = 0;
        // Boyer-Moore Voting: track up to 2 candidates appearing > n/3 times
        for (int x : nums) {
            if (x == a) ca++; // Increment count for candidate a
            else if (x == b) cb++; // Increment count for candidate b
            else if (ca == 0) a = x, ca = 1; // Adopt new candidate a
            else if (cb == 0) b = x, cb = 1; // Adopt new candidate b
            else ca--, cb--;
        }
        // Verify actual counts for both candidates
        ca = cb = 0;
        for (int x : nums) {
            if (x == a) ca++;
            else if (x == b) cb++;
        }
        vector<int> ans;
        if (ca > nums.size() / 3) ans.push_back(a);
        if (cb > nums.size() / 3) ans.push_back(b);
        return ans;
    }
};

class Solution31 {
public:
    vector<int> findErrorNums(vector<int>& nums) {
        int dup = -1, missing = -1;
        // In-place sign negation to find duplicate value
        for (int x : nums) {
            int i = abs(x) - 1; 
            if (nums[i] < 0) dup = abs(x);
            else nums[i] = -nums[i];
        }
        // Positive index + 1 identifies the missing value
        for (int i = 0; i < nums.size(); i++) {
            if (nums[i] > 0) {
                missing = i + 1;
                break;
            }
        }
        return {dup, missing};
    }
};

class Solution37 {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        int n = matrix.size(), m = matrix[0].size();
        bool firstRow = false, firstCol = false;

        // Check first row and first column
        for (int j = 0; j < m; j++)
            if (matrix[0][j] == 0) firstRow = true;

        for (int i = 0; i < n; i++)
            if (matrix[i][0] == 0) firstCol = true;

        // Use first row and column as markers
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < m; j++) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0;
                    matrix[0][j] = 0;
                }
            }
        }

        // Set cells to zero
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < m; j++) {
                if (matrix[i][0] == 0 || matrix[0][j] == 0)
                    matrix[i][j] = 0;
            }
        }

        // Handle first row
        if (firstRow){
            fill(matrix[0].begin(), matrix[0].end(), 0);
        }

        // Handle first column
        if (firstCol){
            for (int i = 0; i < n; i++)
                matrix[i][0] = 0;
        }
    }
};

class Solution39 {
    int m, n;

    void dfs(vector<vector<char>>& board, int r, int c) {
        if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] != 'O') return;
        board[r][c] = '#';
        dfs(board, r + 1, c);
        dfs(board, r - 1, c);
        dfs(board, r, c + 1);
        dfs(board, r, c - 1);
    }

public:
    void solve(vector<vector<char>>& board) {
        m = (int)board.size();
        if (m == 0) return;
        n = (int)board[0].size();

        for (int i = 0; i < m; ++i) {
            if (board[i][0] == 'O') dfs(board, i, 0);
            if (board[i][n - 1] == 'O') dfs(board, i, n - 1);
        }
        for (int j = 0; j < n; ++j) {
            if (board[0][j] == 'O') dfs(board, 0, j);
            if (board[m - 1][j] == 'O') dfs(board, m - 1, j);
        }

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (board[i][j] == 'O') board[i][j] = 'X';
                else if (board[i][j] == '#') board[i][j] = 'O'; 
            }
        }
    }
};

class Solution41 {
public:
    int orangesRotting(vector<vector<int>>& grid) {
        int m = (int)grid.size();
        int n = (int)grid[0].size();
        queue<pair<int, int>> q;
        int freshCount = 0;

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 2) {
                    q.push({i, j});
                } else if (grid[i][j] == 1) {
                    freshCount++;
                }
            }
        }

        if (freshCount == 0) return 0;

        int minutes = 0;
        int dirs[4][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!q.empty() && freshCount > 0) {
            int sz = (int)q.size();
            for (int k = 0; k < sz; ++k) {
                auto [r, c] = q.front();
                q.pop();

                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                        grid[nr][nc] = 2;
                        freshCount--;
                        q.push({nr, nc});
                    }
                }
            }
            minutes++;
        }
        return (freshCount == 0) ? minutes : -1;
    }
};

class Solution43 {
public:
    string convert(string s, int numRows) {
        if (numRows == 1) return s;
        vector<string> rows(numRows);
        int row = 0, dir = 1;
        for (char c : s) {
            rows[row] += c;
            if (row == 0) dir = 1;
            if (row == numRows - 1) dir = -1;
            row += dir;
        }
        string ans;
        for (string& x : rows) ans += x;
        return ans;
    }
};

class Solution46 {
public:
    bool isValid(string s) {
        stack<char> st;
        for (char c : s) {
            if (c == '(' || c == '{' || c == '[') {
                st.push(c);
            } else {
                if (st.empty()) return false;
                char top = st.top();
                st.pop();
                if ((c == ')' && top != '(') ||
                    (c == '}' && top != '{') ||
                    (c == ']' && top != '[')) {
                    return false;
                }
            }
        }
        return st.empty();
    }
};

class Solution47 {
public:
    vector<string> ans;

    void solve(string s, int open, int close, int n) {
        if (s.size() == 2 * n) {
            ans.push_back(s);
            return;
        }

        if (open < n) // If we can still add an opening parenthesis
            solve(s + "(", open + 1, close, n);

        if (close < open) // If we can add a closing parenthesis without violating the balance
            solve(s + ")", open, close + 1, n);
    }

    vector<string> generateParenthesis(int n) {
        solve("", 0, 0, n);
        return ans;
    }
};

class Solution49 {
public:
    vector<vector<string>> groupAnagrams(vector<string>& strs) {
        unordered_map<string, vector<string>> groups;

        for (const string& s : strs) {
            string key = s;
            sort(key.begin(), key.end());
            groups[key].push_back(s);
        }

        vector<vector<string>> result;
        result.reserve(groups.size());
        for (auto& [_, vec] : groups) {
            result.push_back(std::move(vec));
        }
        return result;
    }
};

class Solution50 {
public:
    bool isIsomorphic(string s, string t) {
        if (s.size() != t.size()) return false;
        int a[256] = {}, b[256] = {};

        for (int i = 0; i < s.size(); i++) {
            if (a[s[i]] != b[t[i]]) return false;
            a[s[i]] = i + 1; // Store last seen index + 1 to avoid default 0 confusion
            b[t[i]] = i + 1; // Store last seen index + 1 to avoid default 0 confusion
        }

        return true;
    }
};

class Solution51 {
public:
    int findKthElementinSortedArrays(const vector<int> &a, const vector<int> &b, int k) {
        if (a.size() > b.size())
            return findKthElementinSortedArrays(b, a, k);
        int n = a.size(), m = b.size();
        int low = max(0, k - m);
        int high = min(k, n);

        while (low <= high) {
            int p1 = (low + high) / 2;
            int p2 = k - p1;
            int left1 = (p1 == 0) ? INT_MIN : a[p1 - 1];
            int left2 = (p2 == 0) ? INT_MIN : b[p2 - 1];
            int right1 = (p1 == n) ? INT_MAX : a[p1];
            int right2 = (p2 == m) ? INT_MAX : b[p2];

            if (left1 <= right2 && left2 <= right1)
                return max(left1, left2);
            if (left1 > right2)
                high = p1 - 1;
            else
                low = p1 + 1;
        }

        return -1;
    }
    int findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        int totalLen = (int)nums1.size() + (int)nums2.size();
        if (totalLen % 2 == 1) {
            return findKthElementinSortedArrays(nums1, nums2, totalLen / 2 + 1);
        } else {
            int leftMedian = findKthElementinSortedArrays(nums1, nums2, totalLen / 2);
            int rightMedian = findKthElementinSortedArrays(nums1, nums2, totalLen / 2 + 1);
            return (leftMedian + rightMedian) / 2.0;
        }
    }
};

class Solution52 {
public:
    int search(vector<int>& nums, int target) {
        int low = 0, high = nums.size() - 1;

        while (low <= high) {
            int mid = (low + high) / 2;

            if (nums[mid] == target) return mid;

            // Left half is sorted
            if (nums[low] <= nums[mid]) {
                if (nums[low] <= target && target < nums[mid])
                    high = mid - 1;
                else
                    low = mid + 1;
            }
            // Right half is sorted
            else {
                if (nums[mid] < target && target <= nums[high])
                    low = mid + 1;
                else
                    high = mid - 1;
            }
        }

        return -1;
    }
};

class Solution54 {
public:
    int singleNonDuplicate(vector<int>& nums) {
        int low = 0, high = nums.size() - 1, ans = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (mid % 2 == 1) mid--; // Ensure mid is even for pair comparison
            if (nums[mid] == nums[mid + 1]) { // Pair found, single element is in the right half
                low = mid + 2;
            } else { // No pair, single element is in the left half or at mid
                ans = nums[mid];
                high = mid - 1;
            }
        }
        return ans;
    }
};

class Solution70 {
  public:
    unordered_map<int, int> pos;
    int index = 0;

    TreeNode *build(vector<int> &preorder, int left, int right) {
        if (left > right)
            return nullptr;

        // Current preorder element is the root
        int val = preorder[index];
        index++;
        TreeNode *root = new TreeNode(val);

        // Find root position in inorder
        int mid = pos[val];

        // Build left and right subtrees
        root->left = build(preorder, left, mid - 1);
        root->right = build(preorder, mid + 1, right);

        return root;
    }

    TreeNode *buildTree(vector<int> &preorder, vector<int> &inorder) {
        for (int i = 0; i < inorder.size(); i++)
            pos[inorder[i]] = i;
        int n = preorder.size();
        return build(preorder, 0, n - 1);
    }
};

class Solution71 {
