        if (!node)
            return 0;
        int leftH = checkHeight(node->left);
        int rightH = checkHeight(node->right);
        if (leftH == -1 || rightH == -1 || abs(leftH - rightH) > 1)
            return -1;
        return 1 + max(leftH, rightH);
    }

  public:
    bool isBalanced(TreeNode *root) {
        return checkHeight(root) != -1;
    }
};

class Solution72 {
    int globalMax;

    int maxGain(TreeNode *node) {
        if (!node)
            return 0;
        int leftGain = max(0, maxGain(node->left));
        int rightGain = max(0, maxGain(node->right));
        globalMax = max(globalMax, node->val + leftGain + rightGain);
        return node->val + max(leftGain, rightGain);
    }

  public:
    int maxPathSum(TreeNode *root) {
        globalMax = INT_MIN;
        maxGain(root);
        return globalMax;
    }
};

class Solution73 {
  public:
    int countNodes(TreeNode *node) {
        if (!node)
            return 0;
        return 1 + countNodes(node->left) + countNodes(node->right);
    }

    int kthSmallest(TreeNode *root, int k) {
        stack<TreeNode *> st;
        TreeNode *curr = root;

        while (curr || !st.empty()) {
            while (curr) {
                st.push(curr);
                curr = curr->left;
            }
            curr = st.top();
            st.pop();

            if (--k == 0) {
                return curr->val;
            }
            curr = curr->right;
        }
        return -1;
    }
    int kthlargest(TreeNode *root, int k) {
        return kthSmallest(root, countNodes(root) - k + 1);
    }
};

class Solution74 {
