class Solution90 {
  public:
    int calculate(string s) {
        stack<int> st;
        int result = 0, num = 0, sign = 1;

        for (char c : s) {
            if (isdigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '+') {
                result += sign * num;
                num = 0;
                sign = 1;
            } else if (c == '-') {
                result += sign * num;
                num = 0;
                sign = -1;
            } else if (c == '(') {
                st.push(result);
                st.push(sign);
                result = 0;
                sign = 1;
            } else if (c == ')') {
                result += sign * num;
                num = 0;
                result *= st.top();
                st.pop();
                result += st.top();
                st.pop();
            }
        }
        return result + sign * num;
    }
};

class Solution91 {
  public:
    vector<int> maxSlidingWindow(vector<int> &nums, int k) {
        deque<int> dq;
        vector<int> result;
        result.reserve(nums.size() - k + 1);

        for (int i = 0; i < (int)nums.size(); ++i) {
            while (!dq.empty() && dq.front() <= i - k)
                dq.pop_front();
            while (!dq.empty() && nums[dq.back()] <= nums[i])
                dq.pop_back();
            dq.push_back(i);
            if (i >= k - 1)
                result.push_back(nums[dq.front()]);
        }
        return result;
    }
};

class Solution92 {
    struct TupleCmp {
        bool operator()(const tuple<int, int, int> &a, const tuple<int, int, int> &b) const {
            return get<0>(a) > get<0>(b);
        }
    };

  public:
    vector<vector<int>> kSmallestPairs(vector<int> &nums1, vector<int> &nums2, int k) {
        vector<vector<int>> ans;
        if (nums1.empty() || nums2.empty() || k <= 0)
            return ans;

        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, TupleCmp> pq;
        for (int i = 0; i < (int)nums1.size() && i < k; ++i) {
            pq.emplace(nums1[i] + nums2[0], i, 0);
        }

        while (!pq.empty() && (int)ans.size() < k) {
            auto [sum, i, j] = pq.top();
            pq.pop();
            ans.push_back({nums1[i], nums2[j]});
            if (j + 1 < (int)nums2.size()) {
                pq.emplace(nums1[i] + nums2[j + 1], i, j + 1);
            }
        }
        return ans;
    }
};

class Solution93 {
  public:
    vector<int> nextGreaterElement(vector<int> &nums1, vector<int> &nums2) {
        unordered_map<int, int> mp;
        stack<int> st;

        for (int x : nums2) {
            while (!st.empty() && st.top() < x) {
                mp[st.top()] = x;
                st.pop();
            }
            st.push(x);
        }

        vector<int> ans;
        ans.reserve(nums1.size());
        for (int x : nums1) {
            ans.push_back(mp.count(x) ? mp[x] : -1);
        }
        return ans;
    }
};

class Solution94 {
public:
    vector<int> nextGreaterElements(vector<int>& nums) {
        int n = (int)nums.size();
        vector<int> result(n, -1);
        stack<int> st; // stores indices

        // Iterate through array twice to simulate circular traversal
        for (int i = 0; i < 2 * n; ++i) {
            int idx = i % n;
            while (!st.empty() && nums[st.top()] < nums[idx]) {
                result[st.top()] = nums[idx];
                st.pop();
            }
            if (i < n) {
                st.push(idx);
            }
        }
        return result;
    }
};

class Solution97 {
public:
    int maxResult(vector<int>& nums, int k) {
        int n = (int)nums.size();

        // dp[i] = maximum score possible when reaching index i
        vector<int> dp(n);

        // Starting position
        dp[0] = nums[0];

        // Stores indices.
        // dp values of these indices are in decreasing order.
        deque<int> dq;

        dq.push_back(0); // Starting index

        for (int i = 1; i < n; ++i) {

            // Remove indices that are more than k positions behind.
            while (!dq.empty() && dq.front() < i - k) {
                dq.pop_front();
            }

            // Front contains the index with maximum dp value
            // among the last k reachable positions.
            dp[i] = nums[i] + dp[dq.front()];

            // Remove indices having smaller or equal dp values.
            // Current index is better because it has a >= score
            // and is more recent.
            while (!dq.empty() && dp[dq.back()] <= dp[i]) {
                dq.pop_back();
            }

            // Add current index.
            dq.push_back(i);
        }

        return dp[n - 1];
    }
};

class Solution98 {
public:
    vector<vector<int>> memo;

    bool solve(int i, int j, string& s, string& p) {
        // Pattern finished: string must also be finished
        if (j == p.size()) return i == s.size();
        // Return cached result
        if (memo[i][j] != -1) return memo[i][j];

        // Check if current characters match
        bool firstMatch = i < s.size() && (p[j] == s[i] || p[j] == '.');
        bool ans;
        // Next character is '*'
        if (j + 1 < p.size() && p[j + 1] == '*') {
            // Skip '*' OR use it to match current character
            ans = solve(i, j + 2, s, p) || (firstMatch && solve(i + 1, j, s, p));
        }
        else {
            // Match current characters and move forward
            ans = firstMatch && solve(i + 1, j + 1, s, p);
        }

        return memo[i][j] = ans;
    }

    bool isMatch(string s, string p) {
        int m = s.size();
        int n = p.size();

        // -1 means not computed
        memo.assign(m + 1, vector<int>(n + 1, -1));

        return solve(0, 0, s, p);
    }
};

class Solution100 {
public:
    int uniquePaths(int m, int n) {
        vector<int> dp(n, 1);
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[j] += dp[j - 1];
            }
        }
        return dp[n - 1];
    }
};

class Solution101 {
public:
    int minDistance(string word1, string word2) {
        int m = word1.size(), n = word2.size();
        vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0)); // dp[i][j] = min operations to convert word1[0..i-1] to word2[0..j-1]

        for (int i = 1; i <= m; ++i) dp[i][0] = i; // deleting all characters from word1
        for (int j = 1; j <= n; ++j) dp[0][j] = j; // inserting all characters to word1 to form word2

        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (word1[i - 1] == word2[j - 1]) {
                    dp[i][j] = dp[i - 1][j - 1]; // if characters match, no operation needed
                } else { // if they don't match, consider all three operations and take the minimum
                    dp[i][j] = 1 + min({
                        dp[i - 1][j],    // Delete
                        dp[i][j - 1],    // Insert
                        dp[i - 1][j - 1] // Replace
                    });
                }
            }
        }
        return dp[m][n]; // minimum operations to convert word1 to word2
    }
};

class Solution102 {
public:
    int minimumTotal(vector<vector<int>>& triangle) {
        int n = triangle.size();
        vector<int> dp = triangle[n - 1];

        for (int row = n - 2; row >= 0; row--) {
            for (int col = 0; col <= row; col++) {
                dp[col] = triangle[row][col] + min(dp[col], dp[col + 1]);
            }
        }

        return dp[0];
    }
};

