class Solution {
public:
    bool canJump(vector<int>& a) {
        int n = a.size();
        int mx = 0;

        for (int i = 0; i < n; ++i) {
            if (i > mx) return false;
            mx = max(mx, i + a[i]);
            if (mx >= n - 1) return true; // if the farthest reachable index is beyond or at the last index, we can reach the end
        }
        return true;
    }
};

class Solution {
public:
    int candy(vector<int>& r) {
        int n = r.size();
        vector<int> c(n, 1);

        for (int i = 1; i < n; ++i) {
            if (r[i] > r[i - 1]) {
                c[i] = c[i - 1] + 1;
            }
        }

        for (int i = n - 2; i >= 0; --i) {
            if (r[i] > r[i + 1]) {
                c[i] = max(c[i], c[i + 1] + 1);
            }
        }

        return accumulate(c.begin(), c.end(), 0);
    }
};

class Solution {
public:
    vector<vector<int>> insert(vector<vector<int>>& a, vector<int>& nw) {
        vector<vector<int>> ans;
        int i = 0, n = a.size();

        // 1. Add all intervals ending before nw starts
        while (i < n && a[i][1] < nw[0]) {
            ans.push_back(a[i++]);
        }

        // 2. Merge all overlapping intervals with nw
        while (i < n && a[i][0] <= nw[1]) {
            nw[0] = min(nw[0], a[i][0]);
            nw[1] = max(nw[1], a[i][1]);
            i++;
        }
        ans.push_back(nw);

        // 3. Add all remaining intervals
        while (i < n) {
            ans.push_back(a[i++]);
        }

        return ans;
    }
};

class Solution {
public:
    bool compareIntervalEnds(const vector<int>& a, const vector<int>& b) {
        return a[1] < b[1];
    }

    int eraseOverlapIntervals(vector<vector<int>>& a) {
        if (a.empty()) return 0;
        sort(a.begin(), a.end(), compareIntervalEnds);

        int kept = 1;
        int prevEnd = a[0][1];

        for (int i = 1; i < (int)a.size(); ++i) {
            if (a[i][0] >= prevEnd) {
                kept++;
                prevEnd = a[i][1];
            }
        }
        return (int)a.size() - kept;
    }
};

