class Solution {
public:
    int minMeetingRooms(vector<vector<int>>& a) {
        int n = a.size();
        vector<int> starts(n), ends(n);
        for (int i = 0; i < n; ++i) {
            starts[i] = a[i][0];
            ends[i]   = a[i][1];
        }
        sort(starts.begin(), starts.end());
        sort(ends.begin(), ends.end());

        int rooms = 0, maxRooms = 0;
        int i = 0, j = 0;

        while (i < n) {
            if (starts[i] < ends[j]) {
                rooms++;
                maxRooms = max(maxRooms, rooms);
                i++;
            } else {
                rooms--;
                j++;
            }
        }
        return maxRooms;
    }
};

class Solution {
public:
    bool compareBalloonEnds(const vector<int>& a, const vector<int>& b) {
        return a[1] < b[1];
    }

    int findMinArrowShots(vector<vector<int>>& a) {
        if (a.empty()) return 0;
        sort(a.begin(), a.end(), compareBalloonEnds);

        int arrows = 1;
        long long curEnd = a[0][1];

        for (int i = 1; i < (int)a.size(); ++i) {
            if (a[i][0] > curEnd) {
                arrows++;
                curEnd = a[i][1];
            }
        }
        return arrows;
    }
};

class Solution {
public:
    vector<vector<int>> intervalIntersection(vector<vector<int>>& a, vector<vector<int>>& b) {
        vector<vector<int>> ans;
        int i = 0, j = 0;
        int n = a.size(), m = b.size();

        while (i < n && j < m) {
            int lo = max(a[i][0], b[j][0]);
            int hi = min(a[i][1], b[j][1]);

            if (lo <= hi) {
                ans.push_back({lo, hi});
            }

            if (a[i][1] < b[j][1]) {
                i++;
            } else {
                j++;
            }
        }
        return ans;
    }
};

class Solution {
public:
    bool carPooling(vector<vector<int>>& trips, int capacity) {
        int diff[1001] = {0};
        for (const auto& t : trips) {
            diff[t[1]] += t[0];
            diff[t[2]] -= t[0];
        }

        int cur = 0;
        for (int i = 0; i <= 1000; ++i) {
            cur += diff[i];
            if (cur > capacity) return false;
        }
        return true;
    }
};

class Solution {
public:
    vector<int> corpFlightBookings(vector<vector<int>>& bookings, int n) {
        vector<int> diff(n + 1, 0);
        for (const auto& b : bookings) {
            diff[b[0] - 1] += b[2];
            diff[b[1]]     -= b[2];
        }

        vector<int> ans(n);
        int cur = 0;
        for (int i = 0; i < n; ++i) {
            cur += diff[i];
            ans[i] = cur;
        }
        return ans;
    }
};

class MyCalendar {
    map<int, int> mp; // start -> end
public:
    MyCalendar() {}

    bool book(int start, int end) {
        auto it = mp.upper_bound(start);
        if (it != mp.end() && it->first < end) {
            return false;
        }
        if (it != mp.begin() && prev(it)->second > start) {
            return false;
        }
        mp[start] = end;
        return true;
    }
};

class MyCalendarTwo {
    vector<pair<int, int>> bookings;
    vector<pair<int, int>> overlaps;
public:
    MyCalendarTwo() {}

    bool book(int start, int end) {
        for (const auto& [s, e] : overlaps) {
            if (max(start, s) < min(end, e)) return false;
        }
        for (const auto& [s, e] : bookings) {
            if (max(start, s) < min(end, e)) {
                overlaps.push_back({max(start, s), min(end, e)});
            }
        }
        bookings.push_back({start, end});
        return true;
    }
};

