class Solution {
public:
    vector<int> advantageCount(vector<int>& a, vector<int>& b) {
        int n = a.size();
        sort(a.begin(), a.end());

        vector<pair<int, int>> sortedB(n);
        for (int i = 0; i < n; ++i) sortedB[i] = {b[i], i};
        sort(sortedB.begin(), sortedB.end());

        vector<int> ans(n);
        int lo = 0, hi = n - 1;

        for (int x : a) {
            if (x > sortedB[lo].first) {
                ans[sortedB[lo].second] = x;
                lo++;
            } else {
                ans[sortedB[hi].second] = x;
                hi--;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int bagOfTokensScore(vector<int>& tokens, int power) {
        sort(tokens.begin(), tokens.end());

        int l = 0, r = (int)tokens.size() - 1;
        int score = 0, maxScore = 0;

        while (l <= r) {
            if (power >= tokens[l]) {
                power -= tokens[l++];
                score++;
                maxScore = max(maxScore, score);
            } else if (score > 0 && l < r) {
                power += tokens[r--];
                score--;
            } else {
                break;
            }
        }
        return maxScore;
    }
};

class Solution {
public:
    int minSetSize(vector<int>& arr) {
        unordered_map<int, int> freq;
        for (int x : arr) freq[x]++;

        vector<int> counts;
        for (const auto& [val, count] : freq) counts.push_back(count);
        sort(counts.rbegin(), counts.rend());

        int removed = 0, ans = 0;
        int half = arr.size() / 2;

        for (int c : counts) {
            removed += c;
            ans++;
            if (removed >= half) break;
        }
        return ans;
    }
};

class Solution {
public:
    int minIncrementForUnique(vector<int>& a) {
        sort(a.begin(), a.end());

        int ans = 0;
        for (int i = 1; i < (int)a.size(); ++i) {
            if (a[i] <= a[i - 1]) {
                int needed = a[i - 1] + 1;
                ans += needed - a[i];
                a[i] = needed;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int minMoves(vector<int>& a, int limit) {
        int n = a.size();
        vector<int> diff(2 * limit + 2, 0);

        for (int i = 0; i < n / 2; ++i) {
            int x = min(a[i], a[n - 1 - i]);
            int y = max(a[i], a[n - 1 - i]);

            // [2, 2 * limit] default: 2 moves
            diff[2] += 2;
            diff[2 * limit + 1] -= 2;

            // [1 + x, limit + y]: 1 move
            diff[1 + x] -= 1;
            diff[limit + y + 1] += 1;

            // [x + y]: 0 moves
            diff[x + y] -= 1;
            diff[x + y + 1] += 1;
        }

        int ans = n, cur = 0;
        for (int s = 2; s <= 2 * limit; ++s) {
            cur += diff[s];
            ans = min(ans, cur);
        }
        return ans;
    }
};

class Solution {
