        for (int i = 0; i < (int)a.size(); i += 3) {
            if (a[i + 2] - a[i] > k) {
                return {};
            }
            ans.push_back({a[i], a[i + 1], a[i + 2]});
        }
        return ans;
    }
};

class Solution {
