        for (int i = 1; i < m; ++i) {
            warehouse[i] = min(warehouse[i], warehouse[i - 1]);
        }
        sort(boxes.begin(), boxes.end());

        int ans = 0;
        int bIdx = 0;

        for (int i = m - 1; i >= 0 && bIdx < (int)boxes.size(); --i) {
            if (boxes[bIdx] <= warehouse[i]) {
                ans++;
                bIdx++;
            }
        }
        return ans;
    }
};

class Solution {
