class Solution {
public:
    int lastStoneWeightII(vector<int>& stones) {
        int total = accumulate(stones.begin(), stones.end(), 0);
        int target = total / 2;

        vector<bool> dp(target + 1, false);
        dp[0] = true;

        for (int s : stones) {
            for (int i = target; i >= s; --i) {
                dp[i] = dp[i] || dp[i - s];
            }
        }

        for (int i = target; i >= 0; --i) {
            if (dp[i]) {
                return total - 2 * i;
            }
        }
        return 0;
    }
};

class Solution {
public:
    int furthestBuilding(vector<int>& h, int bricks, int ladders) {
        priority_queue<int, vector<int>, greater<int>> pq; // min-heap of ladder climbs

        for (int i = 0; i < (int)h.size() - 1; ++i) {
            int diff = h[i + 1] - h[i];
            if (diff > 0) {
                pq.push(diff);
                if ((int)pq.size() > ladders) {
                    bricks -= pq.top();
                    pq.pop();
                }
                if (bricks < 0) {
                    return i;
                }
            }
        }
        return (int)h.size() - 1;
    }
};

class Solution {
public:
    int minRefuelStops(int target, int startFuel, vector<vector<int>>& stations) {
        priority_queue<int> pq; // max-heap of passed fuel capacities
        long long curReach = startFuel;
        int stops = 0, i = 0, n = stations.size();

        while (curReach < target) {
            while (i < n && stations[i][0] <= curReach) {
                pq.push(stations[i][1]);
                i++;
            }

            if (pq.empty()) return -1;

            curReach += pq.top();
            pq.pop();
            stops++;
        }
        return stops;
    }
};

class Solution {
public:
    struct Cell3D {
        int h, r, c;
    };

    struct Cell3DCompare {
        bool operator()(const Cell3D& a, const Cell3D& b) const {
            return a.h > b.h;
        }
    };

    int trapRainWater(vector<vector<int>>& g) {
        int m = g.size(), n = g[0].size();
        if (m <= 2 || n <= 2) return 0;

        priority_queue<Cell3D, vector<Cell3D>, Cell3DCompare> pq;
        vector<vector<bool>> vis(m, vector<bool>(n, false));

        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (r == 0 || r == m - 1 || c == 0 || c == n - 1) {
                    pq.push({g[r][c], r, c});
                    vis[r][c] = true;
                }
            }
        }

        int trapped = 0;
        int maxBoundary = 0;
        const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!pq.empty()) {
            auto [h, r, c] = pq.top();
            pq.pop();

            maxBoundary = max(maxBoundary, h);

            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !vis[nr][nc]) {
                    vis[nr][nc] = true;
                    if (g[nr][nc] < maxBoundary) {
                        trapped += maxBoundary - g[nr][nc];
                    }
                    pq.push({g[nr][nc], nr, nc});
                }
            }
        }
        return trapped;
    }
};

class Solution {
public:
    struct ClassGain {
        int p, t;
        double gain() const {
            return (double)(p + 1) / (t + 1) - (double)p / t;
        }
    };

    struct ClassGainCompare {
        bool operator()(const ClassGain& a, const ClassGain& b) const {
            return a.gain() < b.gain(); // max-heap by marginal gain
        }
    };

    double maxAverageRatio(vector<vector<int>>& classes, int extraStudents) {
        priority_queue<ClassGain, vector<ClassGain>, ClassGainCompare> pq;
        for (const auto& c : classes) {
            pq.push({c[0], c[1]});
        }

        while (extraStudents-- > 0) {
            auto top = pq.top();
            pq.pop();
            top.p++;
            top.t++;
            pq.push(top);
        }

        double sumRatio = 0.0;
        while (!pq.empty()) {
            auto top = pq.top();
            pq.pop();
            sumRatio += (double)top.p / top.t;
        }
        return sumRatio / classes.size();
    }
};

class Solution {
public:
    long long totalCost(vector<int>& costs, int k, int candidates) {
        int n = costs.size();
        priority_queue<int, vector<int>, greater<int>> leftPq, rightPq;

        int l = 0, r = n - 1;

        for (int i = 0; i < candidates && l <= r; ++i) {
            leftPq.push(costs[l++]);
        }
        for (int i = 0; i < candidates && l <= r; ++i) {
            rightPq.push(costs[r--]);
        }

        long long ans = 0;

        while (k-- > 0) {
            int leftVal = leftPq.empty() ? INT_MAX : leftPq.top();
            int rightVal = rightPq.empty() ? INT_MAX : rightPq.top();

            if (leftVal <= rightVal) {
                ans += leftVal;
                leftPq.pop();
                if (l <= r) {
                    leftPq.push(costs[l++]);
                }
            } else {
                ans += rightVal;
                rightPq.pop();
                if (l <= r) {
                    rightPq.push(costs[r--]);
                }
            }
        }
        return ans;
    }
};

class Solution {
public:
    bool isNStraightHand(vector<int>& hand, int groupSize) {
        if ((int)hand.size() % groupSize != 0) return false;

        map<int, int> mp;
        for (int x : hand) mp[x]++;

        while (!mp.empty()) {
            int start = mp.begin()->first;
            for (int i = 0; i < groupSize; ++i) {
                int card = start + i;
                if (!mp.count(card)) return false;
                if (--mp[card] == 0) {
                    mp.erase(card);
                }
            }
        }
        return true;
    }
};

class SolutionValidArrangement {
    unordered_map<int, vector<int>> adj;
    vector<int> path;

    void dfs(int u) {
        auto& edges = adj[u];
        while (!edges.empty()) {
            int v = edges.back();
            edges.pop_back();
            dfs(v);
        }
        path.push_back(u);
    }

public:
    vector<vector<int>> validArrangement(vector<vector<int>>& pairs) {
        unordered_map<int, int> inDeg, outDeg;
        for (const auto& p : pairs) {
            adj[p[0]].push_back(p[1]);
            outDeg[p[0]]++;
            inDeg[p[1]]++;
        }

        int startNode = pairs[0][0];
        for (const auto& [node, out] : outDeg) {
            if (out - inDeg[node] == 1) {
                startNode = node;
                break;
            }
        }

        path.clear();
        dfs(startNode);
        reverse(path.begin(), path.end());

        vector<vector<int>> ans;
        for (int i = 0; i < (int)path.size() - 1; ++i) {
            ans.push_back({path[i], path[i + 1]});
        }
        return ans;
    }
};

