        string s = to_string(n);
        int mark = s.size();

        for (int i = (int)s.size() - 1; i > 0; --i) {
            if (s[i - 1] > s[i]) {
                s[i - 1]--;
                mark = i;
            }
        }

        for (int i = mark; i < (int)s.size(); ++i) {
            s[i] = '9';
        }
        return stoi(s);
    }
};

