class Solution {
public:
    bool compareEnvelopes(const vector<int>& a, const vector<int>& b) {
        if (a[0] != b[0]) return a[0] < b[0]; // width ascending
        return a[1] > b[1];                   // height descending
    }

    int maxEnvelopes(vector<vector<int>>& env) {
        sort(env.begin(), env.end(), compareEnvelopes);

        vector<int> tails;
        for (const auto& e : env) {
            int h = e[1];
            auto it = lower_bound(tails.begin(), tails.end(), h);
            if (it == tails.end()) {
                tails.push_back(h);
            } else {
                *it = h;
            }
        }
        return tails.size();
    }
};

class Solution {
public:
    int findUnsortedSubarray(vector<int>& a) {
        int n = a.size();
        int curMax = INT_MIN, right = -1;
        int curMin = INT_MAX, left = -1;

        for (int i = 0; i < n; ++i) {
            curMax = max(curMax, a[i]);
            if (a[i] < curMax) {
                right = i;
            }
        }

        for (int i = n - 1; i >= 0; --i) {
            curMin = min(curMin, a[i]);
            if (a[i] > curMin) {
                left = i;
            }
        }

        return (right == -1 ? 0 : right - left + 1);
    }
};

class Solution {
public:
    struct HuffmanNode {
        char data;
        int freq;
        HuffmanNode *left, *right;
        HuffmanNode(char d, int f) : data(d), freq(f), left(nullptr), right(nullptr) {}
    };

    struct HuffmanNodeCompare {
        bool operator()(HuffmanNode* a, HuffmanNode* b) const {
            return a->freq > b->freq; // min-heap
        }
    };

    void buildHuffmanCodes(HuffmanNode* root, string code, vector<string>& ans) {
        if (!root) return;
        if (!root->left && !root->right) {
            ans.push_back(code);
            return;
        }
        buildHuffmanCodes(root->left, code + "0", ans);
        buildHuffmanCodes(root->right, code + "1", ans);
    }

    vector<string> huffmanCodes(string s, vector<int>& f, int n) {
        priority_queue<HuffmanNode*, vector<HuffmanNode*>, HuffmanNodeCompare> pq;
        for (int i = 0; i < n; ++i) {
            pq.push(new HuffmanNode(s[i], f[i]));
        }

        while (pq.size() > 1) {
            HuffmanNode* l = pq.top(); pq.pop();
            HuffmanNode* r = pq.top(); pq.pop();

            HuffmanNode* parent = new HuffmanNode('$', l->freq + r->freq);
            parent->left = l;
            parent->right = r;
            pq.push(parent);
        }

        vector<string> ans;
        buildHuffmanCodes(pq.top(), "", ans);
        return ans;
    }
};

class Solution {
public:
    struct KnapsackItem {
        int value, weight;
    };

    bool compareKnapsackRatio(const KnapsackItem& a, const KnapsackItem& b) {
        double r1 = (double)a.value / a.weight;
        double r2 = (double)b.value / b.weight;
        return r1 > r2;
    }

    double fractionalKnapsack(int w, vector<KnapsackItem>& arr, int n) {
        sort(arr.begin(), arr.end(), compareKnapsackRatio);

        double totalVal = 0.0;
        for (int i = 0; i < n && w > 0; ++i) {
            if (w >= arr[i].weight) {
                totalVal += arr[i].value;
                w -= arr[i].weight;
            } else {
                totalVal += (double)arr[i].value * w / arr[i].weight;
                w = 0;
                break;
            }
        }
        return totalVal;
    }
};

class Solution1 {
public:
    int equalSubstring(string s, string t, int maxCost) {
        int l = 0, cost = 0, ans = 0;

        for (int r = 0; r < (int)s.size(); r++) {
            cost += abs(s[r] - t[r]);

            while (cost > maxCost) {
                cost -= abs(s[l] - t[l]);
                l++;
            }

            ans = max(ans, r - l + 1);
        }

        return ans;
    }
};

class Solution2 {
public:
    long long countPalindromePairs(vector<string>& words) {
        unordered_map<int, long long> freq;
        long long ans = 0;

        for (string& s : words) {
            int mask = 0;

            for (char c : s)
                mask ^= (1 << (c - 'a'));

            // All frequencies become even
            ans += freq[mask];

            // Exactly one character has odd frequency
            for (int i = 0; i < 26; i++)
                ans += freq[mask ^ (1 << i)];

            freq[mask]++;
        }

        return ans;
    }
};

class Solution3 {
public:
    long long maxProfit(vector<int>& profit, int K) {
        int n = profit.size();
        int half = n / 2;

        vector<long long> value(n);

        for (int i = 0; i < n; i++)
            value[i] = profit[i] + profit[(i + half) % n];

        long long sum = 0;

        for (int i = 0; i < K; i++)
            sum += value[i];

        long long ans = sum;

        for (int start = 1; start < n; start++) {
            sum -= value[start - 1];
            sum += value[(start + K - 1) % n];

            ans = max(ans, sum);
        }

        return ans;
    }
};

class Solution4 {
public:
    int maxDistinctElements(vector<int>& nums) {
        sort(nums.begin(), nums.end());

        int ans = 0;
        int last = INT_MIN;

        for (int x : nums) {
            if (x - 1 > last) {
                last = x - 1;
                ans++;
            } else if (x > last) {
                last = x;
                ans++;
            } else if (x + 1 > last) {
                last = x + 1;
                ans++;
            }
        }

        return ans;
    }
};

