class Solution6 {
public:
    vector<int> rateLimiter(
        vector<string>& users,
        vector<int>& times,
        int T,
        int K
    ) {
        unordered_map<string, queue<int>> mp;
        vector<int> ans;

        for (int i = 0; i < (int)users.size(); i++) {
            auto& q = mp[users[i]];
            int time = times[i];

            while (!q.empty() && q.front() < time - T)
                q.pop();

            if ((int)q.size() < K) {
                q.push(time);
                ans.push_back(1);
            } else {
                ans.push_back(0);
            }
        }

        return ans;
    }
};

class Solution7 {
    vector<int> parent, sz, mx;

    int find(int x) {
        return parent[x] == x
            ? x
            : parent[x] = find(parent[x]);
    }

public:
    vector<long long> getStrength(
        int n,
        vector<int>& from,
        vector<int>& to
    ) {
        parent.resize(n + 1);
        sz.assign(n + 1, 1);
        mx.resize(n + 1);

        long long total = 0;

        for (int i = 1; i <= n; i++) {
            parent[i] = i;
            mx[i] = i;
            total += i;
        }

        vector<long long> ans;

        for (int i = 0; i < (int)from.size(); i++) {
            int a = find(from[i]);
            int b = find(to[i]);

            if (a != b) {
                total -= mx[a] + mx[b];

                if (sz[a] < sz[b])
                    swap(a, b);

                parent[b] = a;
                sz[a] += sz[b];
                mx[a] = max(mx[a], mx[b]);

                total += mx[a];
            }

            ans.push_back(total);
        }

        return ans;
    }
};

class Solution8 {
public:
    long long countTriplets(vector<int>& nums, int d) {
        vector<long long> count(d, 0);
        vector<long long> pairCount(d, 0);

        long long ans = 0;

        for (int x : nums) {
            int r = ((x % d) + d) % d;

            // Existing pairs that need remainder -r
            ans += pairCount[(d - r) % d];

            // Create new pairs with previous elements
            for (int rem = 0; rem < d; rem++) {
                pairCount[(rem + r) % d] += count[rem];
            }

            count[r]++;
        }

        return ans;
    }
};

class Solution9 {
    long long rangeSum(long long l, long long r) {
        if (l > r) return 0;

        return (l + r) * (r - l + 1) / 2;
    }

public:
    long long sequenceSum(int i, int j, int k) {
        return rangeSum(i, j)
             + rangeSum(k, j - 1);
    }
};

class Solution10 {
public:
    string smallestString(string word, string sub) {
        int n = word.size();
        int m = sub.size();

        string ans = "";

        for (int start = 0; start + m <= n; start++) {
            string cur = word;
            bool ok = true;

            for (int j = 0; j < m; j++) {
                int pos = start + j;

                if (cur[pos] != '?' &&
                    tolower(cur[pos]) != sub[j]) {
                    ok = false;
                    break;
                }

                cur[pos] = sub[j];
            }

            if (!ok)
                continue;

            for (char& c : cur) {
                if (c == '?')
                    c = 'a';
                else
                    c = tolower(c);
            }

            if (ans.empty() || cur < ans)
                ans = cur;
        }

        return ans;
    }
};

class Solution11 {
