        int n = nums.size();

        if (k == 1)
            return n;

        int streak = 1;
        int ans = 0;

        for (int i = 1; i < n; i++) {
            if (nums[i] > nums[i - 1])
                streak++;
            else
                streak = 1;

            if (streak >= k)
                ans++;
        }

        return ans;
    }
};

class Solution12 {
