    int countSubstrings(string s) {
        int n = s.size();
        int ans = 0;

        for (int center = 0; center < 2 * n - 1; center++) {
            int l = center / 2;
            int r = l + center % 2;

            while (l >= 0 && r < n &&
                   s[l] == s[r]) {
                ans++;
                l--;
                r++;
            }
        }

        return ans;
    }
};

class Solution13 {
public:
    int earliestFreeSlot(
        vector<pair<int, int>>& intervals,
        int k
    ) {
        sort(intervals.begin(), intervals.end());

        vector<pair<int, int>> merged;

        for (auto [start, end] : intervals) {
            if (merged.empty() ||
                start > merged.back().second) {
                merged.push_back({start, end});
            } else {
                merged.back().second =
                    max(merged.back().second, end);
            }
        }

        int freeStart = 0;

        for (auto [start, end] : merged) {
            if (start - freeStart >= k)
                return freeStart;

            freeStart = max(freeStart, end);
        }

        return freeStart;
    }
};

class Solution14 {
public:
    vector<long long> solve(
        vector<int>& price,
        vector<int>& queries
    ) {
        sort(price.begin(), price.end());

        int n = price.size();
        vector<long long> prefix(n + 1);

        for (int i = 0; i < n; i++)
            prefix[i + 1] = prefix[i] + price[i];

        vector<long long> ans;

        for (int q : queries) {
            int idx = lower_bound(
                price.begin(),
                price.end(),
                q
            ) - price.begin();

            long long left =
                1LL * q * idx - prefix[idx];

            long long right =
                prefix[n] - prefix[idx]
                - 1LL * q * (n - idx);

            ans.push_back(left + right);
        }

        return ans;
    }
};

class Solution15 {
public:
    int minimumStress(
        int n,
        vector<vector<pair<int, int>>>& graph,
        int source,
        int destination
    ) {
        vector<int> dist(n, INT_MAX);

        priority_queue<
            pair<int, int>,
            vector<pair<int, int>>,
            greater<pair<int, int>>
        > pq;

        dist[source] = 0;
        pq.push({0, source});

        while (!pq.empty()) {
            auto [stress, u] = pq.top();
            pq.pop();

            if (u == destination)
                return stress;

            if (stress != dist[u])
                continue;

            for (auto [v, weight] : graph[u]) {
                int nextStress = max(stress, weight);

                if (nextStress < dist[v]) {
                    dist[v] = nextStress;
                    pq.push({dist[v], v});
                }
            }
        }

        return -1;
    }
};

class Solution16 {
public:
    vector<int> productQueries(
        int n,
        vector<vector<int>>& queries
    ) {
        vector<long long> powers;

        for (int bit = 0; bit < 31; bit++) {
            if (n & (1 << bit))
                powers.push_back(1LL << bit);
        }

        vector<int> ans;

        for (auto& q : queries) {
            int l = q[0];
            int r = q[1];
            int mod = q[2];

            long long product = 1;

            for (int i = l; i <= r; i++)
                product = product * powers[i] % mod;

            ans.push_back(product);
        }

        return ans;
    }
};

class Solution17 {
