            vector<long long>,
            greater<long long>
        > pq(nums.begin(), nums.end());

        long long cost = 0;

        while (pq.size() > 1) {
            long long a = pq.top();
            pq.pop();

            long long b = pq.top();
            pq.pop();

            long long sum = a + b;

            cost += sum;
            pq.push(sum);
        }

        return cost;
    }
};

class Solution18 {
public:
    long long minimumStartingResources(
        vector<int>& worstCase,
        vector<int>& actual
    ) {
        int n = worstCase.size();

        vector<int> order(n);
        iota(order.begin(), order.end(), 0);

        sort(order.begin(), order.end(),
            [&](int a, int b) {

                long long ab = max(
                    1LL * worstCase[a],
                    1LL * actual[a] + worstCase[b]
                );

                long long ba = max(
                    1LL * worstCase[b],
                    1LL * actual[b] + worstCase[a]
                );

                return ab < ba;
            }
        );

        long long consumed = 0;
        long long initial = 0;

        for (int i : order) {
            initial = max(
                initial,
                consumed + worstCase[i]
            );

            consumed += actual[i];
        }

        return initial;
    }
};

