class Solution20 {
public:
    int minOperations(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();

        int ans = INT_MAX;

        for (int target = 0; target < m; target++) {
            int total = 0;
            bool possible = true;

            for (int row = 0; row < n; row++) {
                int best = INT_MAX;

                for (int col = 0; col < m; col++) {
                    if (grid[row][col] == 1) {
                        int dist = abs(col - target);
                        best = min(best, min(dist, m - dist));
                    }
                }

                if (best == INT_MAX) {
                    possible = false;
                    break;
                }

                total += best;
            }

            if (possible)
                ans = min(ans, total);
        }

        return ans == INT_MAX ? -1 : ans;
    }
};

