        vector<int>& value,
        int capacity
    ) {
        vector<int> dp(capacity + 1, 0);

        for (int i = 0; i < (int)weight.size(); i++) {
            for (int w = capacity;
                 w >= weight[i];
                 w--) {

                dp[w] = max(
                    dp[w],
                    dp[w - weight[i]] + value[i]
                );
            }
        }

        return dp[capacity];
    }
};

class Solution23 {
    vector<int> primeFactors(int x) {
        vector<int> factors;

        for (int p = 2; 1LL * p * p <= x; p++) {
            if (x % p == 0) {
                factors.push_back(p);

                while (x % p == 0)
                    x /= p;
            }
        }

        if (x > 1)
            factors.push_back(x);

        return factors;
    }

public:
    vector<int> finalState(
        vector<int>& state,
        vector<int>& nums
    ) {
        int n = state.size();

        vector<int> flip(n + 1, 0);

        for (int x : nums) {
            for (int p : primeFactors(x)) {
                for (int i = p; i <= n; i += p)
                    flip[i] ^= 1;
            }
        }

        for (int i = 1; i <= n; i++) {
            if (flip[i])
                state[i - 1] ^= 1;
        }

        return state;
    }
};

