        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (nums[j] < nums[i]) {
                    if (len[j] + 1 > len[i]) len[i] = len[j] + 1, cnt[i] = cnt[j];
                    else if (len[j] + 1 == len[i]) cnt[i] += cnt[j];
                }
            }
            best = max(best, len[i]);
        }
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            if (len[i] == best) ans += cnt[i];
        }
        return ans;
    }
