class Solution27 {
public:
    vector<int> getUnexpiredTokens(int time_to_live, vector<string> queries) {
        unordered_map<string, int> expiry;
        vector<int> ans;
        for (const string& q : queries) {
            stringstream ss(q);
            string type, token;
            int time;
            ss >> type;
            if (type == "generate") {
                ss >> token >> time;
                expiry[token] = time + time_to_live;
            } else if (type == "renew") {
                ss >> token >> time;
                if (expiry.count(token) && expiry[token] > time) {
                    expiry[token] = time + time_to_live;
                }
            } else { // count
                ss >> time;
                int cnt = 0;
                for (const auto& it : expiry) {
                    if (it.second > time) cnt++;
                }
                ans.push_back(cnt);
            }
        }
        return ans;
    }
};

class Solution28 {
